sys_script_client.script:
function onLoad() {
    try {
        // Check if this is a new record
        var isNewRecord = g_form.isNewRecord();

        if (isNewRecord) {
            // For new records, show appropriate message
            g_form.addInfoMessage("Leave request created. Country and approver will be auto-populated based on your profile.");

            // Add an onChange event for the requested_by field
            g_form.onChange("requested_by", function() {
                // First validate fields
                validateFields();

                // Then calculate duration after a short delay to allow country to be set
                setTimeout(displayDuration, 1000);
            });
        } else {
            // For existing records, validate immediately
            validateFields();
            displayDuration();
        }

        // Add event listeners for fields that affect duration
        g_form.onChange("start_date", function() {
            // Ensure country is set before calculating duration
            ensureCountryAndApprover(function() {
                displayDuration();
            });
        });

        g_form.onChange("end_date", function() {
            // Ensure country is set before calculating duration
            ensureCountryAndApprover(function() {
                displayDuration();
            });
        });

        g_form.onChange("country", displayDuration);
        g_form.onChange("is_half_day", displayDuration);
        g_form.onChange("half_day_period", displayDuration);
    } catch (ex) {
        console.error('Error in onLoad script:', ex);
    }

    function ensureCountryAndApprover(callback) {
        // Check if country and approver are set
        var country = g_form.getValue('country');
        var approver = g_form.getValue('approver');

        if (!country || !approver) {
            // Wait a bit for business rules to set these values
            setTimeout(function() {
                // Check again
                if (!g_form.getValue('country') || !g_form.getValue('approver')) {
                    // Still not set, show warning
                    validateFields();
                }

                // Continue with callback regardless
                if (callback) callback();
            }, 1000);
        } else {
            // Already set, proceed immediately
            if (callback) callback();
        }
    }

    function validateFields() {
        try {
            // Get current values
            var country = g_form.getValue('country');
            var approver = g_form.getValue('approver');

            // Check if either field is not set
            if (!country || !approver) {
                // Create validation message
                var message = "Warning: Required fields not set:\n\n";

                if (!country) {
                    message += "• Country is not set\n";
                }

                if (!approver) {
                    message += "• Approver is not set\n";
                }

                message += "\nPlease contact your system administrator.";

                // Show popup message
                alert(message);
            }
        } catch (ex) {
            console.error('Error validating fields:', ex);
        }
    }

    function displayDuration() {
        try {
            // Get start and end dates
            var startDate = g_form.getValue('start_date');
            var endDate = g_form.getValue('end_date');
            var country = g_form.getValue('country');

            if (!startDate || !endDate || !country) {
                console.log('Missing required fields for duration calculation');
                return;
            }

            // Get current duration value
            var duration = g_form.getValue('duration');

            // If duration exists, display it prominently
            if (duration) {
                var durationValue = parseFloat(duration);
                var durationText = durationValue == 1 ? "1 day" : durationValue + " days";

                // Add duration message
                g_form.addInfoMessage("Leave duration: " + durationText);
            }
        } catch (ex) {
            console.error('Error displaying duration:', ex);
        }
    }
}
